head.script:
scwin.getType = function(info) {
    var rowIndex = info.rowIndex;
    var colIndex = info.colIndex;
    var returnInfo;
    if (dataList1.getCellData(rowIndex, "col2") == 1) {
        returnInfo = {
            id: "dynamic_select_" + rowIndex + "_" + colIndex,
            inputType: "select",
            options: {
                viewType: "icon"
            },
            itemSet: {
                nodeset: "data:dataList2",
                label: "col1",
                value: "col2"
            }
        };
    } else {
        returnInfo = {
            id: "dynamic_text_" + rowIndex + "_" + colIndex,
            inputType: "text",
            options: {}
        };
    }
    if (returnInfo) {
        console.log("[typeGetter] (" + rowIndex + ", " + colIndex + ") : " + returnInfo.inputType);
    }
    return returnInfo;
};
scwin.grd_onviewchange = function(info) {
    //		grd.refreshRow(info.rowIndex);
    grd.refreshCell(info.rowIndex, "col1");
};
scwin.onpageload = function() {
    var jsonData = [{
        "col2": "1"
    }, {
        "col2": "2"
    }, {
        "col2": "a3"
    }];
    dataList1.setJSON(jsonData);
    dataList1.insertRow(0);
    dataList1.insertRow();
    var jsonData2 = [{
        "col1": "a1",
        "col2": "a1"
    }, {
        "col1": "a2",
        "col2": "a2"
    }, {
        "col1": "a3",
        "col2": "a3"
    }];
    dataList2.setJSON(jsonData2);
};
scwin.onpageunload = function() {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#gridView1_cell_0_0', 'key-combo', {
        combo: 'ctrl+c'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#gridView1_cell_1_0', 'key-combo', {
        combo: 'ctrl+v'
    });
}
scwin.setSimulate3 = function() {
    scwin.simulateWrapper('#grd_cell_1_0', 'key-combo', {
        combo: 'TAB'
    });
}
scwin.setSimulate4 = function() {
    scwin.simulateWrapper('#grd_cell_1_0', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_cell_1_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_cell_1_1').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#grd_cell_1_1_text').val(2)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_cell_1_1_text').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_cell_1_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_cell_1_1').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#grd_cell_1_1_text').val(1)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_cell_1_1_text').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+$p.id+'grd_cell_1_0').getElementsByTagName('input').length == 0", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
